import logging
from typing import List, Set, Optional
from .ast import Formula, LogicType, Term
from .unification import unify, Substitution

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("LogicProver")

class Clause:
    """A disjunction of literals."""
    def __init__(self, literals: Set[Formula]):
        self.literals = literals

    def __repr__(self):
        return " ∨ ".join(map(str, self.literals))

class LogicProver:
    def __init__(self):
        self.kb: List[Clause] = []

    def add_axiom(self, formula: Formula):
        """Converts formula to CNF and adds to knowledge base."""
        # Simplified: assuming input is already a clause for this core implementation
        self.kb.append(Clause(set([formula])))

    def resolve(self, c1: Clause, c2: Clause) -> Optional[Clause]:
        """Attempts to resolve two clauses."""
        for l1 in c1.literals:
            for l2 in c2.literals:
                # Check if l1 and l2 are complementary literals
                if self._is_complementary(l1, l2):
                    mgu = unify(self._get_term(l1), self._get_term(l2))
                    if mgu:
                        # Create new clause: (C1 \ {l1}) U (C2 \ {l2})
                        new_lits = (c1.literals - {l1}) | (c2.literals - {l2})
                        # Apply MGU to the resulting clause
                        # (Implementation of apply_mgu_to_clause omitted for brevity)
                        return Clause(new_lits)
        return None

    def _is_complementary(self, l1: Formula, l2: Formula) -> bool:
        if l1.type == LogicType.NOT and l1.children[0] == l2:
            return True
        if l2.type == LogicType.NOT and l2.children[0] == l1:
            return True
        return False

    def _get_term(self, formula: Formula) -> Term:
        # Extract the core term from a literal (ignoring NOT)
        if formula.type == LogicType.NOT:
            return self._get_term(formula.children[0])
        return formula.terms[0] if formula.terms else Term("unknown")

    def prove(self, goal: Formula) -> bool:
        """
        Proves the goal using Resolution Refutation.
        Goal is proven if the KB + {¬goal} leads to an empty clause.
        """
        logger.info(f"Attempting to prove: {goal}")
        
        # Negate goal and add to KB
        negated_goal = Formula(LogicType.NOT, children=[goal])
        clauses = self.kb + [Clause({negated_goal})]
        
        # Simple saturation loop
        processed = set()
        while True:
            new_clauses = []
            for i in range(len(clauses)):
                for j in range(i + 1, len(clauses)):
                    res = self.resolve(clauses[i], clauses[j])
                    if res:
                        if not res.literals:
                            logger.info("Empty clause derived. Proof successful.")
                            return True
                        if res not in clauses:
                            new_clauses.append(res)
            
            if not new_clauses:
                break
            clauses.extend(new_clauses)
            if len(clauses) > 1000: # Safety break
                break
                
        logger.info("Could not derive empty clause. Proof failed.")
        return False